from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Return the sum of square(x) for every x in xs.

    The squares are computed on a thread pool with `workers` threads.
    The result must be identical for every worker count >= 1.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        # Results come back in input order and integer addition is exact,
        # so the total does not depend on the worker count.
        return sum(pool.map(square, xs))


def test_square() -> None:
    assert square(-3) == 9
    assert square(0) == 0


@pytest.mark.parametrize("workers", [1, 2, 4, 8])
def test_matches_serial_sum(workers: int) -> None:
    xs = list(range(-50, 51))
    assert sum_squares(xs, workers=workers) == sum(square(x) for x in xs)


@pytest.mark.parametrize("workers", [1, 3, 16])
def test_empty_list_is_zero(workers: int) -> None:
    assert sum_squares([], workers=workers) == 0


def test_same_result_across_worker_counts() -> None:
    xs = [7, -3, 10**6, 0, 42]
    results = {sum_squares(xs, workers=w) for w in range(1, 9)}
    assert len(results) == 1


def test_default_workers() -> None:
    assert sum_squares([3, 4]) == 25


def test_large_values_are_exact() -> None:
    big = 10**12
    assert sum_squares([big, -big]) == 2 * big * big


def test_rejects_nonpositive_workers() -> None:
    with pytest.raises(ValueError):
        sum_squares([1], workers=0)
